SELECT s.decision AS one_m_decision, s.market_regime, COUNT(*) AS n, SUM(pp.realized_pnl < 0) AS losers, SUM(pp.status = 'STOPPED') AS stopped, SUM(pp.realized_pnl) AS net_pnl, AVG(pp.realized_pnl / NULLIF(pp.entry_price * pp.quantity, 0) * 100) AS avg_pnl_pct FROM crypto_ai.paper_position pp JOIN crypto_ai.trade_signal s ON s.id = pp.signal_id WHERE pp.status IN ('CLOSED','STOPPED') GROUP BY s.decision, s.market_regime ORDER BY n DESC LIMIT 40